 Console.WriteLine("PASS protected cleanup stage CAS, atomic interruption, identity binding and corruption tests");return 0;}catch{Console.WriteLine("FAIL cleanup stage test category "+stage);return 1;}finally{try{if(made){if(Path.GetDirectoryName(directory)!=parent||!Path.GetFileName(directory).StartsWith("SentinelCleanupProbe-")||(File.GetAttributes(directory)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("Cleanup fixture path refused");foreach(string file in Directory.GetFiles(directory)){string name=Path.GetFileName(file);if(name!="admission-stage.bin"&&name!="admission-stage.lock"&&name!=tempName)throw new InvalidOperationException("Unexpected fixture entry");if((File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("Reparse fixture refused");File.Delete(file);}if(fixturePin!=null){fixturePin.Dispose();fixturePin=null;}Directory.Delete(directory,false);}}finally{if(fixturePin!=null)fixturePin.Dispose();if(parentPin!=null)parentPin.Dispose();}}}
